167→// GetSessionDir returns the directory where Entire stores OpenCode session transcripts.
168→// Transcripts are ephemeral handoff files between the TS plugin and the Go hook handler.
169→// Once checkpointed, the data lives on git refs and the file is disposable.
170→// Stored in os.TempDir()/entire-opencode/<sanitized-path>/ to avoid squatting on
171→// OpenCode's own directories (~/.opencode/ is project-level, not home-level).
172→func (a *OpenCodeAgent) GetSessionDir(repoPath string) (string, error) {
173→	// Check for test environment override
174→	if override := os.Getenv("ENTIRE_TEST_OPENCODE_PROJECT_DIR"); override != "" {
175→		return override, nil
176→	}
177→
178→	projectDir := SanitizePathForOpenCode(repoPath)
179→	return filepath.Join(os.TempDir(), "entire-opencode", projectDir), nil
180→}
