212→// ExtractAllUserPrompts extracts all user prompts from raw export JSON transcript bytes.
213→// This is a package-level function used by the condensation path.
214→func ExtractAllUserPrompts(data []byte) ([]string, error) {
215→	session, err := ParseExportSession(data)
216→	if err != nil {
217→		return nil, err
218→	}
219→	if session == nil {
220→		return nil, nil
221→	}
222→
223→	var prompts []string
224→	for _, msg := range session.Messages {
225→		if msg.Info.Role != roleUser {
226→			continue
227→		}
228→		content := ExtractTextFromParts(msg.Parts)
229→		if content != "" {
230→			prompts = append(prompts, content)
231→		}
232→	}
233→	return prompts, nil
234→}
