 37→		d, err := detect.NewDetectorDefaultConfig()
 38→		if err != nil {
 39→			return
 40→		}
 41→		gitleaksDetector = d
 42→	})
 43→	return gitleaksDetector
 44→}
 45→
 46→// region represents a byte range to redact.
 47→type region struct{ start, end int }
 48→
 49→// String replaces secrets in s with "REDACTED" using layered detection:
 50→// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
 51→// 2. Pattern-based: gitleaks regex rules (180+ known secret formats)
 52→// A string is redacted if EITHER method flags it.
 53→func String(s string) string {
 54→	var regions []region
 55→
 56→	// 1. Entropy-based detection.
 57→	for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
 58→		start, end := loc[0], loc[1]
 59→
 60→		// Don't consume characters that are part of JSON/string escape sequences.
 61→		// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
 62→		// (consuming the 'n' from '\n'), and after replacement the '\' would be
 63→		// followed by 'R' from "REDACTED", creating invalid escape '\R'.
 64→		// Only skip for known JSON escape letters to avoid trimming real secrets
 65→		// that happen to follow a literal backslash in decoded content.
 66→		if start > 0 && s[start-1] == '\\' {
 67→			switch s[start] {
 68→			case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
 69→				start++
 70→				if end-start < 10 {
 71→					continue
 72→				}
 73→			}
 74→		}
 75→
 76→		if shannonEntropy(s[start:end]) > entropyThreshold {
 77→			regions = append(regions, region{start, end})
 78→		}
 79→	}
 80→
 81→	// 2. Pattern-based detection via gitleaks.
 82→	if d := getDetector(); d != nil {
 83→		for _, f := range d.DetectString(s) {
 84→			if f.Secret == "" {
 85→				continue
 86→			}
 87→			searchFrom := 0
 88→			for {
 89→				idx := strings.Index(s[searchFrom:], f.Secret)
 90→				if idx < 0 {
 91→					break
 92→				}
 93→				absIdx := searchFrom + idx
 94→				regions = append(regions, region{absIdx, absIdx + len(f.Secret)})
 95→				searchFrom = absIdx + len(f.Secret)
 96→			}
 97→		}
 98→	}
 99→
100→	if len(regions) == 0 {
101→		return s
102→	}
103→
104→	// Merge overlapping regions and build result.
105→	sort.Slice(regions, func(i, j int) bool {
106→		return regions[i].start < regions[j].start
107→	})
108→	merged := []region{regions[0]}
109→	for _, r := range regions[1:] {
110→		last := &merged[len(merged)-1]
111→		if r.start <= last.end {
112→			if r.end > last.end {
113→				last.end = r.end
114→			}
115→		} else {
116→			merged = append(merged, r)
117→		}
118→	}
119→
120→	var b strings.Builder
121→	prev := 0
122→	for _, r := range merged {
123→		b.WriteString(s[prev:r.start])
124→		b.WriteString(RedactedPlaceholder)
125→		prev = r.end
126→	}
127→	b.WriteString(s[prev:])
128→	return b.String()
129→}
130→
131→// Bytes is a convenience wrapper around String for []byte content.
132→func Bytes(b []byte) []byte {
133→	s := string(b)
134→	redacted := String(s)
135→	if redacted == s {
136→		return b
137→	}
138→	return []byte(redacted)
139→}
140→
141→// JSONLBytes is a convenience wrapper around JSONLContent for []byte content.
142→func JSONLBytes(b []byte) ([]byte, error) {
143→	s := string(b)
144→	redacted, err := JSONLContent(s)
145→	if err != nil {
146→		return nil, err
147→	}
148→	if redacted == s {
149→		return b, nil
150→	}
151→	return []byte(redacted), nil
152→}
153→
154→// JSONLContent parses each line as JSON to determine which string values
155→// need redaction, then performs targeted replacements on the raw JSON bytes.
156→// Lines with no secrets are returned unchanged, preserving original formatting.
157→func JSONLContent(content string) (string, error) {
158→	lines := strings.Split(content, "\n")
159→	var b strings.Builder
160→	for i, line := range lines {
161→		if i > 0 {
162→			b.WriteByte('\n')
163→		}
164→		trimmed := strings.TrimSpace(line)
165→		if trimmed == "" {
166→			b.WriteString(line)
167→			continue
168→		}
169→		var parsed any
170→		if err := json.Unmarshal([]byte(trimmed), &parsed); err != nil {
171→			b.WriteString(String(line))
172→			continue
173→		}
174→		repls := collectJSONLReplacements(parsed)
175→		if len(repls) == 0 {
176→			b.WriteString(line)
177→			continue
178→		}
179→		result := line
180→		for _, r := range repls {
181→			origJSON, err := jsonEncodeString(r[0])
182→			if err != nil {
183→				return "", err
184→			}
185→			replJSON, err := jsonEncodeString(r[1])
186→			if err != nil {
187→				return "", err
188→			}
189→			result = strings.ReplaceAll(result, origJSON, replJSON)
190→		}
191→		b.WriteString(result)
192→	}
193→	return b.String(), nil
194→}
195→
196→// collectJSONLReplacements walks a parsed JSON value and collects unique
197→// (original, redacted) string pairs for values that need redaction.
198→func collectJSONLReplacements(v any) [][2]string {
199→	seen := make(map[string]bool)
200→	var repls [][2]string
201→	var walk func(v any)
202→	walk = func(v any) {
203→		switch val := v.(type) {
204→		case map[string]any:
205→			if shouldSkipJSONLObject(val) {
206→				return
207→			}
208→			for k, child := range val {
209→				if shouldSkipJSONLField(k) {
210→					continue
211→				}
212→				walk(child)
213→			}
214→		case []any:
215→			for _, child := range val {
216→				walk(child)
217→			}
218→		case string:
219→			redacted := String(val)
220→			if redacted != val && !seen[val] {
221→				seen[val] = true
222→				repls = append(repls, [2]string{val, redacted})
223→			}
224→		}
225→	}
226→	walk(v)
227→	return repls
228→}
229→
230→// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
231→// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
232→func shouldSkipJSONLField(key string) bool {
233→	if key == "signature" {
234→		return true
235→	}
236→	lower := strings.ToLower(key)
237→
238→	// Skip ID fields
239→	if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
240→		return true
241→	}
242→
243→	// Skip common path and directory fields from agent transcripts.
244→	// These appear frequently in tool calls and are structural, not secrets.
245→	switch lower {
246→	case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
247→		return true
248→	}
249→
250→	return false
251→}
252→
253→// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
254→func shouldSkipJSONLObject(obj map[string]any) bool {
255→	t, ok := obj["type"].(string)
256→	return ok && (strings.HasPrefix(t, "image") || t == "base64")
257→}
258→
259→func shannonEntropy(s string) float64 {
260→	if len(s) == 0 {
261→		return 0
262→	}
263→	freq := make(map[byte]int)
264→	for i := range len(s) {
265→		freq[s[i]]++
266→	}
267→	length := float64(len(s))
268→	var entropy float64
269→	for _, count := range freq {
270→		p := float64(count) / length
271→		entropy -= p * math.Log2(p)
272→	}
273→	return entropy
274→}
275→
276→// jsonEncodeString returns the JSON encoding of s without HTML escaping.
277→func jsonEncodeString(s string) (string, error) {
278→	var buf bytes.Buffer
279→	enc := json.NewEncoder(&buf)
280→	enc.SetEscapeHTML(false)
281→	if err := enc.Encode(s); err != nil {
282→		return "", fmt.Errorf("json encode string: %w", err)
283→	}
284→	return strings.TrimSuffix(buf.String(), "\n"), nil
285→}
