package main

import (
    "fmt"
    "math"
    "os"
    "regexp"
    "strings"

    "github.com/entireio/cli/redact"
)

var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)

func shannonEntropy(s string) float64 {
    if len(s) == 0 { return 0 }
    freq := make(map[byte]int)
    for i := range len(s) { freq[s[i]]++ }
    length := float64(len(s))
    var e float64
    for _, count := range freq {
        p := float64(count) / length
        e -= p * math.Log2(p)
    }
    return e
}

func main() {
    // Check entropy of Gemini IDs
    ids := []string{
        "438e0bba-bbfb-4e3f-ba73-982763f3d484",
        "2adb8b76-d7c6-481f-9575-6dc5f4d29a8f",
