    }
    fmt.Println("=== Gemini ID entropy ===")
    for _, id := range ids {
        matches := secretPattern.FindAllString(id, -1)
        for _, m := range matches {
            e := shannonEntropy(m)
            fmt.Printf("  match=%-40s entropy=%.2f redacted=%v\n", m, e, e > 4.5)
